import sys

def is_stable(sublist):
    SX = set()
    def generate_messages(prefix, depth):
        if prefix:
            SX.add(prefix)
        if depth == len(sublist):
            return
        for s in sublist:
            generate_messages(prefix + s, depth + 1)
    generate_messages("", 0)

    for message in SX:
        k = len(message)
        cyclic_shifts = {message[i:] + message[:i] for i in range(k)}
        if len(cyclic_shifts & SX) != k:
            return False
    return True

def main():
    import sys
    input = sys.stdin.read().splitlines()
    n = int(input[0])
    A = input[1:]
    count = 0
    for start in range(n):
        for end in range(start + 1, n + 1):
            if is_stable(A[start:end]):
                count += 1
    print(count)

main()
